function clozeWord(word=''){
  const str=String(word||'').trim();
  if(str.length<=2)return str;
  return str.split('').map((char,i)=>{
    if(/\s|[-_.,'!]/.test(char))return char;
    if(i===0||i===str.length-1)return char;
    return (i%2===1)?' _ ':' '+char+' ';
  }).join('');
}

async function reviewView(context={}){
  const generation=window.__ylReviewGeneration=(Number(window.__ylReviewGeneration)||0)+1;
  const stillCurrent=()=>routeName()==='review'&&window.__ylReviewGeneration===generation;
  if(window.__ylReviewKeyHandler){window.removeEventListener('keydown',window.__ylReviewKeyHandler);window.__ylReviewKeyHandler=null;}
  const requestedPriority=String(context.priorityMode||routeArg()||'').toLowerCase(),priorityMode=['due','relearning','hard','new'].includes(requestedPriority)?requestedPriority:'';
  const sid=priorityMode?'':String(context.setId||studySetQuery()||''),lesson=context.lesson||studyLessonQuery();
  let lessons=sid?await api('study_lessons',{query:{set_id:sid}}):[];
  const current=lesson?(lessons.find(item=>item.kind===lesson.kind&&String(item.value)===String(lesson.value))||lesson):(lessons.find(item=>item.status!=='done')||lessons[0]||null);
  // Explicit roadmap lessons keep the 20-card lesson behavior. Daily Plan priority routes use
  // dedicated, disjoint SRS queues so Relearning/Hard/New are not mixed or double-counted.
  const lessonMode=!!sid&&!!current&&!context.reviewOnly;
  const batchSize=10;
  const query=priorityMode?{mode:priorityMode,limit:batchSize}:Object.assign({mode:lessonMode?'lesson':'review',set_id:sid,limit:lessonMode?80:batchSize},lessonMode?lessonQuery(current):{}),cards=await api('study_cards',{query});
  if(!stillCurrent())return;
  const showPlan=()=>{if(!sid||!lessons.length)return'';return lessonPlanHtml(lessons,current,'review');};
  const cleanupKeys=()=>{if(window.__ylReviewKeyHandler){window.removeEventListener('keydown',window.__ylReviewKeyHandler);window.__ylReviewKeyHandler=null;}};
  const priorityLabels={due:'SRS đến hạn',relearning:'Relearning',hard:'Hard Cards',new:'Kiến thức mới'};
  const showEmpty=()=>{cleanupKeys();setView(`<div class="study-shell"><div class="empty"><div><div class="bubble-icon">✓</div><h3>${current?'Bạn đã học xong '+esc(current.title):priorityMode?'Đã xử lý hết '+esc(priorityLabels[priorityMode]):'Không còn thẻ đến hạn'}</h3><p>${current?'Hãy chọn bài tiếp theo bên dưới để tiếp tục ngày mai.':priorityMode?'Quay lại Hôm nay để tiếp tục nhiệm vụ ưu tiên kế tiếp.':'Bạn đã xử lý hết lịch ôn hiện tại. Có thể làm Quiz hoặc luyện Listening.'}</p><a class="btn primary" href="#quiz">Làm Quiz</a></div></div>${showPlan()}</div>`);if(sid)bindLessonPlan(lessons,sid);};
  if(!cards.length){showEmpty();return;}

  let idx=0,flipped=false;
  let recallMode=localStorage.getItem('yl_recall_mode')||'recall';
  if(!['flip','recall','cloze','audio'].includes(recallMode))recallMode='recall';
  const pageSize=20;
  const ratings=Array(cards.length).fill(null);
  const revealed=Array(cards.length).fill(false),attempts=Array(cards.length).fill('');
  let savingRating=false;
  const visited=Array(cards.length).fill(false);visited[0]=true;
  const rateNames={1:'Quên',2:'Khó',3:'Nhớ',4:'Rất dễ'};
  const ratedNow=()=>ratings.reduce((n,r)=>n+(r?1:0),0);
  const viewedNow=()=>visited.reduce((n,v)=>n+(v?1:0),0);
  const goTo=n=>{if(n<0||n>=cards.length)return;idx=n;visited[idx]=true;flipped=false;render();};
  const navigatorHtml=()=>{
    const pageCount=Math.ceil(cards.length/pageSize),currentPage=Math.floor(idx/pageSize),start=currentPage*pageSize,end=Math.min(start+pageSize,cards.length);
    const pages=Array.from({length:pageCount},(_,p)=>`<button class="quiz-page-btn ${p===currentPage?'active':''}" data-review-page="${p}" title="Từ ${p*pageSize+1}–${Math.min((p+1)*pageSize,cards.length)}">${p+1}</button>`).join('');
    const nums=Array.from({length:end-start},(_,k)=>{const n=start+k,r=ratings[n];return `<button class="quiz-num-btn ${n===idx?'current':''} ${visited[n]?'review-viewed':''} ${r?'answered review-rated review-rate-'+r:''}" data-review-num="${n}" title="Từ ${n+1}${r?' · '+rateNames[r]:visited[n]?' · Đã xem':''}">${n+1}</button>`;}).join('');
    return `<div class="quiz-navigator review-navigator"><div class="quiz-nav-head"><div><b>${lessonMode?'Danh sách từ của bài học':priorityMode?priorityLabels[priorityMode]:'Danh sách thẻ SRS đến hạn'}</b><small>${lessonMode?'Bài này có đủ '+cards.length+' thẻ · ':''}Đã xem ${viewedNow()}/${cards.length} · Đã đánh giá ${ratedNow()}/${cards.length}</small></div><span>Bấm số hoặc dùng <kbd>←</kbd> <kbd>→</kbd></span></div>${pageCount>1?`<div class="quiz-page-row"><span>Trang</span>${pages}</div>`:''}<div class="quiz-number-row">${nums}</div></div>`;
  };
  const finishReview=async()=>{
    cleanupKeys();
    await loadSideStats();
    if(sid)lessons=await api('study_lessons',{query:{set_id:sid}});
    if(!stillCurrent())return;
    const finished=current?lessons.find(item=>item.key===current.key)||current:null;
    const again=ratings.filter(x=>x===1).length,remembered=ratings.filter(x=>x>=3).length;
    setView(`<div class="study-shell"><div class="result-card"><span class="eyebrow">TỪNG BƯỚC NHỎ, TIẾN BỘ THẬT</span><div class="score">✓</div><h2>Hoàn thành ${cards.length} thẻ</h2><p style="color:var(--muted)">${fmt(remembered)} thẻ bạn nhớ tốt · ${fmt(again)} thẻ cần học lại.<br>${current?`Đã xong lượt học ${esc(current.title)}. `:''}Lịch ôn đã được lưu theo mức độ nhớ bạn chọn.</p><div class="page-actions" style="justify-content:center"><a class="btn soft" href="#dashboard">Về hôm nay</a>${sid?'<a class="btn primary" href="#plan">Tiếp tục lộ trình</a>':'<button class="btn primary" id="review-another-batch">Ôn thêm một lượt →</button>'}</div></div>${sid?lessonPlanHtml(lessons,finished,'review'):''}</div>`);
    $('#review-another-batch')?.addEventListener('click',()=>reviewView({priorityMode}));
    if(sid)bindLessonPlan(lessons,sid);
  };
  const render=()=>{
    const c=cards[idx],savedRating=ratings[idx],allRated=ratedNow()>=cards.length,progress=Math.round(ratedNow()/cards.length*100);

    const detailHtml=()=>`              <span class="label">NGHĨA & CHI TIẾT</span>
              <h2>${esc(c.term)}</h2>
              ${ipaHtml(c.ipa)}
              <div class="definition">${esc(c.definition)}</div>
              ${c.example_en?`<p class="example"><b>${esc(c.example_en)}</b><br>${esc(c.example_vi)}</p>`:''}
              <div class="flash-meta-grid">
                ${c.collocations?`<div class="flash-meta-item"><b>Collocations:</b>${esc(c.collocations)}</div>`:''}
                ${c.pattern?`<div class="flash-meta-item"><b>Sentence Pattern:</b><code>${esc(c.pattern)}</code></div>`:''}
                ${c.word_family?`<div class="flash-meta-item"><b>Word Family:</b>${esc(c.word_family)}</div>`:''}
                ${c.explanation?`<div class="flash-meta-item"><b>Ngữ pháp / Ghi chú:</b>${esc(c.explanation)}</div>`:''}
                ${c.toeic_part?`<div class="flash-meta-item"><b>TOEIC Part:</b>Part ${esc(c.toeic_part)}</div>`:''}
              </div>`;
    let frontHtml='';
    if(recallMode==='recall'){
      frontHtml=`<span class="label">ACTIVE RECALL (VI → EN) · ${esc(c.part_of_speech||'WORD')}</span>
      <div class="definition" style="margin:16px 0">${esc(c.definition)}</div>
      ${c.example_vi?`<p class="example">${esc(c.example_vi)}</p>`:''}
      <p class="example" style="color:var(--primary2)">Thử nhớ lại từ tiếng Anh trước khi kiểm tra.</p>`;
    } else if(recallMode==='cloze'){
      frontHtml=`<span class="label">SPELLING CLOZE RECALL · ${esc(c.part_of_speech||'WORD')}</span>
      <div class="cloze-hint">${esc(clozeWord(c.term))}</div>
      <div class="definition">${esc(c.definition)}</div>
      <p class="example">Nhớ lại chính xác cách viết từ</p>`;
    } else if(recallMode==='audio'){
      frontHtml=`<span class="label">AUDIO FIRST RECALL</span>
      <button class="listen-icon" id="front-audio-btn" type="button" aria-label="Nghe từ để nhớ lại">♫</button>
      <p class="example">Nghe nhận diện từ tiếng Anh trước khi lật thẻ</p>`;
    } else {
      frontHtml=`<span class="label">${esc(c.cefr||'WORD')} · ${esc(c.part_of_speech||'FLASHCARD')}</span>
      <h2>${esc(c.term)}</h2>
      ${ipaHtml(c.ipa)}
      <p class="example">Nhấn thẻ hoặc Space để xem nghĩa</p>`;
    }

    setView(`<div class="study-shell review-shell-with-nav">
      <div class="study-guidance"><div><span class="eyebrow">NHỚ LẠI → KIỂM TRA → TỰ ĐÁNH GIÁ</span><h2>${lessonMode?'Một bài nhỏ, nhớ từng từ.':'Một lượt ôn nhẹ nhàng.'}</h2><p>${lessonMode?'Học trọn bài này, rồi nghỉ hoặc tiếp tục khi bạn sẵn sàng.':`Tối đa ${batchSize} thẻ mỗi lượt. Những thẻ còn lại vẫn nằm trong lịch ôn của bạn.`}</p></div><a class="btn ghost" href="#dashboard">Về hôm nay</a></div>
      <div class="study-top">
        <span class="study-counter">${[`${idx+1}/${cards.length}`,c.set_title,current?.title].filter(Boolean).map(esc).join(' · ')}</span>
        <span class="review-progress-text">${lessonMode?`📘 Chế độ bài học · đủ ${cards.length}/${cards.length} thẻ`:`${priorityMode?esc(priorityLabels[priorityMode]):'↻ Đến hạn & chưa học'} · ${cards.length} thẻ`} · Đã ôn ${ratedNow()}/${cards.length}</span>
        <button class="btn soft" id="speak-card">🔊 Nghe</button>
      </div>
      <div class="progress review-progress-track" role="progressbar" aria-label="Thẻ đã ôn trong lượt này" aria-valuemin="0" aria-valuemax="${cards.length}" aria-valuenow="${ratedNow()}"><i style="width:${progress}%"></i></div>

      <div class="active-recall-bar" role="group" aria-label="Cách ôn từ">
        <button class="active-recall-chip ${recallMode==='recall'?'active':''}" aria-pressed="${recallMode==='recall'}" data-rmode="recall">Nhớ từ tiếng Anh</button>
        <button class="active-recall-chip ${recallMode==='flip'?'active':''}" aria-pressed="${recallMode==='flip'}" data-rmode="flip">Xem từ & nhớ nghĩa</button>
        <button class="active-recall-chip ${recallMode==='cloze'?'active':''}" aria-pressed="${recallMode==='cloze'}" data-rmode="cloze">Nhớ cách viết</button>
        <button class="active-recall-chip ${recallMode==='audio'?'active':''}" aria-pressed="${recallMode==='audio'}" data-rmode="audio">Nghe & nhận diện</button>
      </div>

      <div class="review-card-stage">
        <button class="review-card-arrow prev" id="review-card-prev" ${idx===0?'disabled':''} aria-label="Thẻ trước" title="Từ trước (←)">←</button>
        <div class="flashcard ${flipped?'flipped':''}" id="flashcard" role="button" tabindex="0" aria-label="${flipped?'Ẩn':'Hiện'} đáp án thẻ ${idx+1}" aria-pressed="${flipped}">
          <div class="flash-inner">
            <div class="flash-face front" aria-hidden="${flipped}">
              ${frontHtml}
            </div>
            <div class="flash-face back" aria-hidden="${!flipped}">
${revealed[idx]?detailHtml():''}
            </div>
          </div>
        </div>
        <button class="review-card-arrow next" id="review-card-next" ${idx===cards.length-1?'disabled':''} aria-label="Thẻ tiếp" title="Từ tiếp (→)">→</button>
      </div>
      ${['recall','cloze'].includes(recallMode)?`<div class="recall-input-wrap"><label for="recall-attempt">Thử viết từ bạn nhớ <span>(không bắt buộc)</span></label><div class="recall-input-row"><input id="recall-attempt" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(attempts[idx])}" placeholder="Nhập từ tiếng Anh rồi kiểm tra" ${revealed[idx]?'readonly':''}><button class="btn primary" id="reveal-card">${flipped?'Xem gợi ý':'Kiểm tra đáp án'}</button></div><div id="recall-feedback" aria-live="polite"></div></div>`:'<div class="page-actions review-reveal-actions"><button class="btn primary" id="reveal-card">'+(flipped?'Xem lại gợi ý':'Hiện đáp án')+'</button></div>'}
      <div class="review-key-banner"><span><kbd>Space</kbd> Xem đáp án</span><b>${idx+1} / ${cards.length}</b><span><kbd>1</kbd>–<kbd>4</kbd> Đánh giá · <kbd>←</kbd> <kbd>→</kbd> Đổi thẻ</span></div>
      <div class="rating-row review-rating-row">
        <button class="rate again ${savedRating===1?'selected':''}" data-rate="1" ${savedRating||!revealed[idx]||savingRating?'disabled':''}>1 · Chưa nhớ<small>Học lại sớm</small></button>
        <button class="rate hard ${savedRating===2?'selected':''}" data-rate="2" ${savedRating||!revealed[idx]||savingRating?'disabled':''}>2 · Nhớ khó<small>Ôn gần hơn</small></button>
        <button class="rate good ${savedRating===3?'selected':''}" data-rate="3" ${savedRating||!revealed[idx]||savingRating?'disabled':''}>3 · Đã nhớ<small>Lịch ôn chuẩn</small></button>
        <button class="rate easy ${savedRating===4?'selected':''}" data-rate="4" ${savedRating||!revealed[idx]||savingRating?'disabled':''}>4 · Rất dễ<small>Ôn xa hơn</small></button>
      </div>
      ${savedRating?`<div class="review-saved-note">✓ Đã lưu: <b>${rateNames[savedRating]}</b>. Chọn thẻ tiếp theo khi bạn sẵn sàng.</div>`:`<div class="review-saved-note review-unsaved-note" id="rating-guidance">${revealed[idx]?'So sánh đáp án rồi chọn mức độ nhớ để lưu lịch ôn.':'Hãy nhớ lại và xem đáp án trước khi tự đánh giá.'}</div>`}
      <div class="quiz-step-actions review-step-actions">
        <button class="btn soft" id="review-prev" ${idx===0?'disabled':''}>← Từ trước</button>
        ${allRated?'<button class="btn success" id="review-finish">✓ Hoàn thành phiên ôn</button>':'<span class="quiz-key-hint">Có thể quay lại xem các từ đã chấm</span>'}
        <button class="btn primary" id="review-next" ${idx===cards.length-1?'disabled':''}>Từ tiếp →</button>
      </div>
      ${navigatorHtml()}
      ${showPlan()}
    </div>`);

    const flipCard=()=>{
      flipped=!flipped;if(flipped)revealed[idx]=true;
      const card=$('#flashcard');if(flipped)$('.flash-face.back',card).innerHTML=detailHtml();card.classList.toggle('flipped',flipped);card.setAttribute('aria-pressed',String(flipped));card.setAttribute('aria-label',`${flipped?'Ẩn':'Hiện'} đáp án thẻ ${idx+1}`);
      $('.flash-face.front',card).setAttribute('aria-hidden',String(flipped));$('.flash-face.back',card).setAttribute('aria-hidden',String(!flipped));
      $('#reveal-card').textContent=flipped?'Xem lại gợi ý':'Hiện đáp án';
      $$('[data-rate]').forEach(b=>b.disabled=!!ratings[idx]||!revealed[idx]||savingRating);
      if(revealed[idx]){if($('#recall-attempt'))$('#recall-attempt').readOnly=true;if($('#rating-guidance'))$('#rating-guidance').textContent='So sánh đáp án rồi chọn mức độ nhớ để lưu lịch ôn.';showAttempt();}
    };
    const showAttempt=()=>{const box=$('#recall-feedback');if(!box||!revealed[idx]||!attempts[idx].trim())return;const ok=normalize(attempts[idx])===normalize(c.term);box.innerHTML=`<p class="recall-feedback ${ok?'correct':'try-again'}">${ok?'✓ Bạn đã viết đúng từ.':`Bạn viết “${esc(attempts[idx])}”. Đáp án: <b>${esc(c.term)}</b>. Hãy đọc lại và thử nhớ lần sau.`}</p>`;};
    $('#flashcard').onclick=flipCard;$('#flashcard').onkeydown=e=>{if(e.target!==e.currentTarget)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();flipCard();}};
    $('#reveal-card').onclick=flipCard;
    $('#recall-attempt')?.addEventListener('input',e=>{attempts[idx]=e.target.value;});
    $('#recall-attempt')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(!flipped)flipCard();}});
    showAttempt();
    $('#speak-card').onclick=()=>speak(c.term);
    $('#front-audio-btn')?.addEventListener('click',e=>{e.stopPropagation();speak(c.audio_text||c.term,.82);});
    if(recallMode==='audio'&&!flipped)setTimeout(()=>speak(c.term,.82),250);

    $$('[data-rmode]').forEach(b=>b.onclick=()=>{
      recallMode=b.dataset.rmode;
      localStorage.setItem('yl_recall_mode',recallMode);
      flipped=false;
      render();
    });

    $('#review-prev')?.addEventListener('click',()=>goTo(idx-1));
    $('#review-next')?.addEventListener('click',()=>goTo(idx+1));
    $('#review-card-prev')?.addEventListener('click',()=>goTo(idx-1));
    $('#review-card-next')?.addEventListener('click',()=>goTo(idx+1));
    $('#review-finish')?.addEventListener('click',finishReview);
    $$('[data-review-num]').forEach(button=>button.onclick=()=>goTo(Number(button.dataset.reviewNum)));
    $$('[data-review-page]').forEach(button=>button.onclick=()=>goTo(Number(button.dataset.reviewPage)*pageSize));
    if(sid)bindLessonPlan(lessons,sid);
    $$('[data-rate]').forEach(button=>button.onclick=async()=>{
      if(ratings[idx]||!revealed[idx]||savingRating)return;
      const currentIndex=idx,currentCard=cards[currentIndex],rating=Number(button.dataset.rate);
      savingRating=true;
      $$('[data-rate]').forEach(x=>x.disabled=true);
      try{
        await api('review_rate',{method:'POST',data:{card_id:currentCard.id,rating}});
        ratings[currentIndex]=rating;
        savingRating=false;
        if(!stillCurrent())return;
        render();
        toast(`Đã lưu “${rateNames[rating]}”. Dùng ← → để tiếp tục.`);
      }catch(e){savingRating=false;if(stillCurrent()){toast(e.message,'error');render();}}
    });
  };

  const keyHandler=e=>{
    const tag=(e.target&&e.target.tagName||'').toLowerCase();
    if(['input','textarea','select'].includes(tag)||e.target?.isContentEditable||$('#modal-root').firstElementChild||e.ctrlKey||e.altKey||e.metaKey)return;
    if(e.key==='ArrowRight'){e.preventDefault();if(idx<cards.length-1)goTo(idx+1);}
    else if(e.key==='ArrowLeft'){e.preventDefault();if(idx>0)goTo(idx-1);}
    else if((e.key===' '||e.code==='Space')&&!['button','a'].includes(tag)){e.preventDefault();$('#reveal-card')?.click();}
    else if(/^[1-4]$/.test(e.key)&&revealed[idx]&&!ratings[idx]&&!savingRating){e.preventDefault();$(`[data-rate="${e.key}"]`)?.click();}
  };
  window.__ylReviewKeyHandler=keyHandler;
  window.addEventListener('keydown',keyHandler);
  window.addEventListener('hashchange',cleanupKeys,{once:true});
  render();
}
function localDateString(d=new Date()){const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,10);}
function shiftDate(date,days){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return localDateString(d);}
async function dailyView(){const date=routeArg()&&/^\d{4}-\d{2}-\d{2}$/.test(routeArg())?routeArg():localDateString();const assignment=await api('daily_assignment',{query:{date}});const nav=`<div class="daily-date-nav"><button class="btn soft" id="daily-prev">← Ngày trước</button><input id="daily-date" type="date" value="${esc(date)}"><button class="btn soft" id="daily-next">Ngày sau →</button></div>`;if(!assignment||!assignment.cards?.length){setView(`<div class="page-head"><div><h1>Flashcard theo ngày</h1><p>Admin chọn từ trong kho và phân riêng cho từng ngày.</p></div>${nav}</div><div class="empty"><div><div class="bubble-icon">◫</div><h3>Chưa có flashcard cho ngày này</h3><p>Khi admin xuất bản một bộ cho ${esc(new Date(date+'T12:00:00').toLocaleDateString('vi-VN'))}, nội dung sẽ xuất hiện tại đây.</p></div></div>`);bindDailyDateNav(date);return;}let idx=0,flipped=false,remembered=0;const render=()=>{if(idx>=assignment.cards.length){setView(`<div class="quiz-shell"><div class="result-card"><div class="score">✓</div><h2>Hoàn thành ${assignment.cards.length} flashcard</h2><p style="color:var(--muted)">Bạn đánh dấu nhớ ${remembered}/${assignment.cards.length} từ trong bộ “${esc(assignment.title)}”.</p><div class="page-actions" style="justify-content:center"><a class="btn primary" href="#daily/${esc(date)}">Học lại</a><a class="btn soft" href="#quiz">Làm Quiz</a></div></div></div>`);return;}const c=assignment.cards[idx];setView(`<div class="page-head"><div><span class="set-kicker">${esc(assignment.study_date)}</span><h1>${esc(assignment.title)}</h1><p>${esc(assignment.description||'Bộ flashcard do admin chọn cho ngày này.')} · ${assignment.cards.length} từ</p></div>${nav}</div><div class="study-shell"><div class="study-top"><span class="study-counter">${idx+1}/${assignment.cards.length} · ${esc(c.set_title)}</span><button class="btn soft" id="daily-speak">🔊 Nghe</button></div><div class="flashcard ${flipped?'flipped':''}" id="daily-card"><div class="flash-inner"><div class="flash-face front"><span class="label">${esc(c.cefr||'WORD')} · ${esc(c.part_of_speech||'FLASHCARD')}</span><h2>${esc(c.term)}</h2>${ipaHtml(c.ipa)}<p class="example">Nhấn để xem nghĩa</p></div><div class="flash-face back"><span class="label">NGHĨA</span><div class="definition">${esc(c.definition)}</div>${c.example_en?`<p class="example"><b>${esc(c.example_en)}</b><br>${esc(c.example_vi||'')}</p>`:''}</div></div></div><div class="daily-actions"><button class="btn danger" data-daily-result="0">Cần xem lại</button><button class="btn success" data-daily-result="1">Đã nhớ →</button></div></div>`);bindDailyDateNav(date);$('#daily-card').onclick=()=>{flipped=!flipped;$('#daily-card').classList.toggle('flipped',flipped)};$('#daily-speak').onclick=()=>speak(c.term);$$('[data-daily-result]').forEach(b=>b.onclick=async()=>{const ok=Number(b.dataset.dailyResult);if(ok)remembered++;try{await api('study_event',{method:'POST',data:{mode:'review',set_id:c.set_id,card_id:c.id,result:ok,score:ok?100:35,xp:ok?6:2}});}catch{}idx++;flipped=false;render();});};render();}
function bindDailyDateNav(date){$('#daily-prev')?.addEventListener('click',()=>navigate('daily/'+shiftDate(date,-1)));$('#daily-next')?.addEventListener('click',()=>navigate('daily/'+shiftDate(date,1)));$('#daily-date')?.addEventListener('change',e=>navigate('daily/'+e.target.value));}
async function getPracticeCards(limit=30){return api('study_cards',{query:{mode:'random',limit}});}
async function quizView(){const arg=routeArg();if(arg&&arg!=='random'&&/^\d+$/.test(arg))return assignedQuizView(Number(arg));if(arg==='random')return randomQuizView();const quizzes=await api('quizzes');if(!quizzes.length)return randomQuizView();setView(`<div class="page-head"><div><h1>Đề luyện tập</h1><p>Chọn đề do admin tạo. Bạn vẫn có thể luyện một bài ngẫu nhiên từ thư viện cá nhân.</p></div><div class="page-actions"><a class="btn soft" href="#quiz/random">Quiz ngẫu nhiên</a></div></div><div class="quiz-catalog">${quizzes.map(q=>`<a class="quiz-catalog-card" href="#quiz/${q.id}"><div><span class="set-kicker">${q.available_date?esc(q.available_date):'MỞ TỰ DO'}</span><h3>${esc(q.title)}</h3><p>${esc(q.description||'Đề luyện tập do admin biên soạn.')}</p></div><span class="quiz-count">${fmt(q.question_count)} câu →</span></a>`).join('')}</div>`);}
function practiceDistractors(q,cards,valueKey='definition',count=3){
  const val=c=>String(c?.[valueKey]||'').trim(),target=val(q),qid=String(q.id);
  const scored=shuffle(cards.filter(c=>String(c.id)!==qid&&val(c)&&val(c)!==target)).map(c=>{
    let score=0;
    if(q.topic&&c.topic&&String(q.topic).toLowerCase()===String(c.topic).toLowerCase())score+=5;
    if(q.part_of_speech&&c.part_of_speech&&String(q.part_of_speech).toLowerCase()===String(c.part_of_speech).toLowerCase())score+=4;
    if(q.card_type&&c.card_type&&q.card_type===c.card_type)score+=2;
    if(q.difficulty&&c.difficulty&&Math.abs(Number(q.difficulty)-Number(c.difficulty))<=1)score+=2;
    return {c,score};
  }).sort((a,b)=>b.score-a.score);
  const out=[];
  for(const x of scored){const v=val(x.c);if(v&&!out.includes(v)){out.push(v);if(out.length>=count)break;}}
  return out;
}
function chunkListeningText(text=''){const words=String(text).trim().split(/\s+/).filter(Boolean),chunks=[];for(let i=0;i<words.length;i+=4)chunks.push(words.slice(i,i+4).join(' '));return chunks.join(' / ');}
function textSimilarity(a,b){a=normalize(a);b=normalize(b);if(!a&&!b)return 1;if(!a||!b)return 0;const aw=a.split(' '),bw=b.split(' ');let same=0,n=Math.max(aw.length,bw.length);for(let i=0;i<Math.min(aw.length,bw.length);i++)if(aw[i]===bw[i])same++;return same/Math.max(1,n);}
async function randomQuizView(){const cards=await getPracticeCards(40);if(cards.length<2)return noCards();let qs=shuffle(cards).slice(0,Math.min(10,cards.length)),idx=0,score=0;const render=()=>{if(idx>=qs.length){setView(resultHtml(score,qs.length,'Quiz ngẫu nhiên'));return;}const q=qs[idx],pool=practiceDistractors(q,cards,'definition',3),opts=shuffle([q.definition,...pool]);if(opts.length<2){idx++;render();return;}setView(`<div class="quiz-shell"><div class="question-card"><span class="q-meta">QUIZ NGẪU NHIÊN · CÂU ${idx+1}/${qs.length}${q.topic?' · '+esc(q.topic):''}</span><h2>${esc(q.term)}</h2><p class="hint">${esc(q.ipa||'Chọn nghĩa đúng')} · Distractor ưu tiên cùng topic/POS/độ khó.</p><div class="options">${opts.map(o=>`<button class="option" data-opt="${esc(o)}">${esc(o)}</button>`).join('')}</div></div></div>`);$$('[data-opt]').forEach(b=>b.onclick=async()=>{const correct=b.dataset.opt===q.definition;$$('[data-opt]').forEach(x=>{x.disabled=true;if(x.dataset.opt===q.definition)x.classList.add('correct');});if(!correct)b.classList.add('wrong');if(correct)score++;await api('study_event',{method:'POST',data:{mode:'quiz',set_id:q.set_id,card_id:q.id,result:correct?1:0,score:correct?100:0,xp:correct?8:2,context:{question:q.term,user_answer:b.dataset.opt,correct_answer:q.definition,error_type:'VOCABULARY',topic:q.topic||''}}});setTimeout(()=>{idx++;render();},650);});};render();}
async function assignedQuizView(id){
  const quiz=await api('quiz_get',{query:{id}}),qs=quiz.questions||[];
  if(!qs.length){setView('<div class="empty"><h3>Đề chưa có câu hỏi.</h3></div>');return;}
  let idx=0;
  const pageSize=20;
  const answers=Array(qs.length).fill(null);
  const optionOrders=qs.map(q=>shuffle([q.correct_answer,q.wrong_answer_1,q.wrong_answer_2,q.wrong_answer_3].filter(v=>v!==null&&v!==undefined&&String(v).trim()!=='')));

  const scoreNow=()=>answers.reduce((n,a)=>n+(a&&a.correct?1:0),0);
  const answeredNow=()=>answers.reduce((n,a)=>n+(a?1:0),0);
  const finish=()=>{const done=answeredNow();if(done<qs.length){toast(`Bạn còn ${qs.length-done} câu chưa làm. Hãy hoàn thành trước khi nộp bài.`,'error');return;}setView(resultHtml(scoreNow(),qs.length,quiz.title));};
  const goTo=n=>{if(n<0||n>=qs.length)return;idx=n;render();};

  const navigatorHtml=()=>{
    const pageCount=Math.ceil(qs.length/pageSize),currentPage=Math.floor(idx/pageSize),start=currentPage*pageSize,end=Math.min(start+pageSize,qs.length);
    const pages=Array.from({length:pageCount},(_,p)=>`<button class="quiz-page-btn ${p===currentPage?'active':''}" data-q-page="${p}" title="Câu ${p*pageSize+1}–${Math.min((p+1)*pageSize,qs.length)}">${p+1}</button>`).join('');
    const nums=Array.from({length:end-start},(_,k)=>{const n=start+k,a=answers[n];return `<button class="quiz-num-btn ${n===idx?'current':''} ${a?'answered':''} ${a&&a.correct?'corrected':''} ${a&&!a.correct?'wronged':''}" data-q-num="${n}" title="Câu ${n+1}">${n+1}</button>`;}).join('');
    return `<div class="quiz-navigator">
      <div class="quiz-nav-head"><div><b>Danh sách câu hỏi</b><small>${answeredNow()}/${qs.length} câu đã làm</small></div><span>← → dùng phím mũi tên để chuyển câu</span></div>
      ${pageCount>1?`<div class="quiz-page-row"><span>Trang</span>${pages}</div>`:''}
      <div class="quiz-number-row">${nums}</div>
    </div>`;
  };

  const render=()=>{
    const q=qs[idx],opts=optionOrders[idx],answer=answers[idx];
    setView(`<div class="quiz-shell quiz-shell-with-nav">
      <div class="question-card">
        <div class="quiz-question-top"><span class="q-meta">${esc(quiz.title)} · CÂU ${idx+1}/${qs.length}</span><span class="quiz-progress-text">Đã làm ${answeredNow()}/${qs.length}</span></div>
        <h2>${esc(q.question)}</h2>
        <div class="options">${opts.map(o=>`<button class="option ${answer&&o===q.correct_answer?'correct':''} ${answer&&o===answer.value&&!answer.correct?'wrong':''}" data-opt="${esc(o)}" ${answer?'disabled':''}>${esc(o)}</button>`).join('')}</div>
        <div id="quiz-explain">${answer&&q.explanation?`<div class="quiz-explain">${esc(q.explanation)}</div>`:''}</div>
        <div class="quiz-step-actions">
          <button class="btn soft" id="quiz-prev" ${idx===0?'disabled':''}>← Câu trước</button>
          <span class="quiz-key-hint">Phím <kbd>←</kbd> <kbd>→</kbd></span>
          ${idx<qs.length-1?'<button class="btn primary" id="quiz-next">Câu tiếp →</button>':`<button class="btn primary" id="quiz-submit">Nộp bài (${answeredNow()}/${qs.length})</button>`}
        </div>
      </div>
      ${navigatorHtml()}
    </div>`);

    $$('[data-opt]').forEach(b=>b.onclick=async()=>{
      if(answers[idx])return;
      const currentIndex=idx,currentQ=qs[currentIndex],value=b.dataset.opt,correct=value===currentQ.correct_answer;
      answers[currentIndex]={value,correct};
      render();
      try{await api('study_event',{method:'POST',data:{mode:'quiz',set_id:currentQ.set_id||null,card_id:currentQ.card_id||null,result:correct?1:0,score:correct?100:0,xp:correct?10:3,context:{source_key:`admin_quiz:${id}:q:${currentQ.id||currentIndex}`,source_id:String(currentQ.id||currentIndex),question:currentQ.question,user_answer:value,correct_answer:currentQ.correct_answer,explanation:currentQ.explanation||'',error_type:currentQ.card_id?'VOCABULARY':'UNKNOWN'}}});}catch{}
    });
    const prev=$('#quiz-prev');if(prev)prev.onclick=()=>goTo(idx-1);
    const next=$('#quiz-next');if(next)next.onclick=()=>goTo(idx+1);
    const submit=$('#quiz-submit');if(submit)submit.onclick=finish;
    $$('[data-q-num]').forEach(b=>b.onclick=()=>goTo(Number(b.dataset.qNum)));
    $$('[data-q-page]').forEach(b=>b.onclick=()=>goTo(Number(b.dataset.qPage)*pageSize));
  };

  const keyHandler=e=>{
    const tag=(e.target&&e.target.tagName||'').toLowerCase();
    if(['input','textarea','select','button'].includes(tag)||e.target?.isContentEditable)return;
    if(e.key==='ArrowRight'){e.preventDefault();if(idx<qs.length-1)goTo(idx+1);}
    else if(e.key==='ArrowLeft'){e.preventDefault();if(idx>0)goTo(idx-1);}
  };
  window.addEventListener('keydown',keyHandler);
  window.addEventListener('hashchange',()=>window.removeEventListener('keydown',keyHandler),{once:true});
  render();
}
function resultHtml(score,total,label){const pct=Math.round(score/Math.max(1,total)*100);return `<div class="quiz-shell"><div class="result-card"><div class="score">${pct}%</div><h2>${esc(label)} hoàn thành</h2><p style="color:var(--muted)">${score}/${total} câu đúng</p><div class="page-actions" style="justify-content:center"><button class="btn primary" onclick="location.reload()">Làm lại</button><a class="btn soft" href="#dashboard">Tổng quan</a></div></div></div>`;}
function noCards(){setView(`<div class="empty"><div><div class="bubble-icon">Aa</div><h3>Chưa đủ flashcard</h3><p>Hãy tạo hoặc import một bộ từ trước khi luyện tập.</p><a class="btn primary" href="#sets">Mở thư viện</a></div></div>`);}
const practiceMeta={listening:{title:'Listening',icon:'♫',desc:'Nghe nội dung do admin biên soạn và chọn đáp án đúng.'},fill:{title:'Điền từ',icon:'✎',desc:'Điền đáp án vào câu/bài tập do admin biên soạn.'},matching:{title:'Matching',icon:'⌘',desc:'Ghép các cặp nội dung do admin tạo.'},speaking:{title:'Speaking AI',icon:'◉',desc:'Luyện các câu nói do admin giao và nhận phản hồi phát âm.'}};
function practiceCatalogHtml(type,packs){const m=practiceMeta[type];return `<div class="page-head"><div><h1>${m.title}</h1><p>${m.desc}</p></div><div class="page-actions"><a class="btn soft" href="#${type}/random">Luyện ngẫu nhiên từ flashcard</a></div></div><div class="quiz-catalog">${packs.map(p=>`<a class="quiz-catalog-card" href="#${type}/${p.id}"><div><span class="set-kicker">${p.available_date?esc(p.available_date):'MỞ TỰ DO'}</span><h3>${esc(p.title)}</h3><p>${esc(p.description||m.desc)}</p></div><span class="quiz-count">${fmt(p.item_count)} mục →</span></a>`).join('')}</div>`;}


